func isPathSafe(path: string) -> bool {
  // 절대 경로 차단
  if path.startsWith("/") {
    return false
  }

  // 상위 디렉토리 접근 차단 (../)
  if path.contains("..") {
    return false
  }

  // null byte 차단
  if path.contains("\0") {
    return false
  }

  // 숨김 파일 차단 (.env, .git, .htaccess 등)
  if path.contains("/.") {
    return false
  }
  if path.startsWith(".") {
    return false
  }

  // 허용된 확장자만
  if isAllowedExtension(path) {
    return true
  }

  return false
}

func isAllowedExtension(path: string) -> bool {
  let allowedExts: [string] = [
    ".html", ".css", ".js", ".json",
    ".png", ".jpg", ".jpeg", ".gif", ".svg",
    ".woff", ".woff2", ".ttf", ".eot"
  ]

  for ext in allowedExts {
    if path.endsWith(ext) {
      return true
    }
  }

  return false
}

