// ============================================================================
// FreeLang API 서버 (메인 프로그램)
// 정식 FreeLang 모듈 - 컴파일 가능, 독립 실행 가능
// freec api-main.free && ./api-main
// ============================================================================

use "std/net"
use "std/json"
use "std/http"

type Blog = {
  id: i32,
  title: string,
  excerpt: string,
  date: string,
  author: string,
  category: string,
  views: i32
}

type APIResponse = {
  status: i32,
  contentType: string,
  body: string
}

func main() -> void {
  println("")
  println("╔═══════════════════════════════════════════════════════╗")
  println("║  🔌 FreeLang API 서버 (정식 모듈)                   ║")
  println("╚═══════════════════════════════════════════════════════╝")
  println("")

  let port: i32 = 8001
  let host: string = "127.0.0.1"

  println("📍 포트: " + i32ToString(port))
  println("📍 호스트: " + host)
  println("")

  println("📋 API 엔드포인트:")
  println("  GET  /api/posts       - 블로그 목록")
  println("  GET  /api/posts/:id   - 블로그 상세")
  println("  GET  /api/theme       - 테마 설정")
  println("  GET  /api/health      - 상태 확인")
  println("")

  // API 서버 시작
