  }
}

// ──────────────────────────────────────────────────────────────────────────
// 프록시 서버 구조
// ──────────────────────────────────────────────────────────────────────────

func createProxyServer(host: string, port: i32) -> ProxyServer {
  let upstreams: [Upstream] = []

  upstreams.push({
    id: "server-1-http",
    host: "127.0.0.1",
    port: 8000,
    weight: 5,
    healthy: true,
    requestCount: 0
  })

  upstreams.push({
    id: "server-2-api",
    host: "127.0.0.1",
    port: 8001,
    weight: 3,
    healthy: true,
    requestCount: 0
  })

  return {
    host: host,
    port: port,
    socket: 0,
    running: false,
    upstreams: upstreams,
    totalRequests: 0
  }
}

// ──────────────────────────────────────────────────────────────────────────
// 서버 시작/중지
// ──────────────────────────────────────────────────────────────────────────

func startProxyServer(server: ProxyServer) -> bool {
  server.running = true
  return true
}

func stopProxyServer(server: ProxyServer) -> void {
  server.running = false
}

// ──────────────────────────────────────────────────────────────────────────
// 로드 밸런싱
// ──────────────────────────────────────────────────────────────────────────

func selectUpstream(upstreams: [Upstream]) -> Upstream {
  // 건강한 업스트림만 선택
  let healthy: [Upstream] = []
  for upstream in upstreams {
    if upstream.healthy {
      healthy.push(upstream)
    }
  }

  if healthy.length() == 0 {
    return upstreams[0]
  }

  if healthy.length() == 1 {
    return healthy[0]
  }

  // 가중치 기반 라운드로빈
  let totalWeight = 0
  for upstream in healthy {
    totalWeight = totalWeight + upstream.weight
  }

  // 간단한 선택 (실제로는 난수 기반)
  let current = 0
  for upstream in healthy {
    current = current + upstream.weight
    if current >= (totalWeight / 2) {
      return upstream
    }
  }

  return healthy[0]
}

