// ============================================================================
// FreeLang API 서버 (메인 프로그램)
// 정식 FreeLang 모듈 - 컴파일 가능, 독립 실행 가능
// freec api-main.free && ./api-main
// ============================================================================

use "std/net"
use "std/json"
use "std/http"

type Blog = {
  id: i32,
  title: string,
  excerpt: string,
  date: string,
  author: string,
  category: string,
  views: i32
}

type APIResponse = {
  status: i32,
  contentType: string,
  body: string
}

func main() -> void {
  println("")
  println("╔═══════════════════════════════════════════════════════╗")
  println("║  🔌 FreeLang API 서버 (정식 모듈)                   ║")
  println("╚═══════════════════════════════════════════════════════╝")
  println("")

  let port: i32 = 8001
  let host: string = "127.0.0.1"

  println("📍 포트: " + i32ToString(port))
  println("📍 호스트: " + host)
  println("")

  println("📋 API 엔드포인트:")
  println("  GET  /api/posts       - 블로그 목록")
  println("  GET  /api/posts/:id   - 블로그 상세")
  println("  GET  /api/theme       - 테마 설정")
  println("  GET  /api/health      - 상태 확인")
  println("")

  // API 서버 시작
  let server = createAPIServer(host, port)
  if startAPIServer(server) {
    println("✅ API 서버 시작됨")
    println("🔗 http://localhost:" + i32ToString(port) + "/api/posts")
    println("")
    println("⌨️  Ctrl+C로 종료")
    println("")

    // 메인 루프
    runAPILoop(server)
  } else {
    println("❌ API 서버 시작 실패")
  }
}

// ──────────────────────────────────────────────────────────────────────────
// API 서버 구조
// ──────────────────────────────────────────────────────────────────────────

type APIServer = {
  host: string,
  port: i32,
  socket: i32,
  running: bool,
  requestCount: i32,
  blogs: [Blog],
  dbConnected: bool
}

func createAPIServer(host: string, port: i32) -> APIServer {
  let blogs = createSampleBlogs()

  // 🔧 Phase 2: 데이터베이스 연결 준비
  let dbConnected = true  // 실제: database connect call

  return {
    host: host,
    port: port,
    socket: 0,
    running: false,
    requestCount: 0,
    blogs: blogs,
    dbConnected: dbConnected
  }
}

// ──────────────────────────────────────────────────────────────────────────
// 샘플 데이터
// ──────────────────────────────────────────────────────────────────────────

func createSampleBlogs() -> [Blog] {
  let blogs: [Blog] = []

  blogs.push({
    id: 1,
    title: "FreeLang 시작하기",
    excerpt: "FreeLang으로 첫 프로젝트를 시작해보세요",
